# Hypothesis: a concrete subclass in a diamond of two abstract branches is instantiable only when the combined MRO supplies every abstract member, and ABC.register does not give a class the abstract interface for checkers.
from abc import ABC, abstractmethod
from typing import reveal_type


class Shape(ABC):
    @property
    @abstractmethod
    def sides(self) -> int: ...

    @abstractmethod
    def area(self) -> float: ...


class HasSides(Shape):
    @property
    def sides(self) -> int:
        return 4


class HasArea(Shape):
    def area(self) -> float:
        return 2.0


class Square(HasSides, HasArea):
    pass


class Partial(HasSides):
    pass


class Tag:
    pass


Shape.register(Tag)


def try_instantiate(cls: type[Shape]) -> str:
    try:
        cls()
    except TypeError:
        return 'rejected'
    return 'accepted'


def try_partial() -> str:
    try:
        Partial()  # expect-error
    except TypeError:
        return 'rejected'
    return 'accepted'


sq = Square()
reveal_type(sq.sides)
reveal_type(sq.area())
assert sq.sides == 4 and sq.area() == 2.0
assert try_instantiate(Square) == 'accepted'
assert try_instantiate(Shape) == 'rejected'
assert try_instantiate(HasSides) == 'rejected'
assert try_partial() == 'rejected'
assert isinstance(Tag(), Shape)
assert not issubclass(Tag, HasSides)
